import{_ as o,o as a,c as t,a3 as n}from"./chunks/framework.cNy3aYYk.js";const m=JSON.parse('{"title":"Calendar — Deployment","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Calendar — Deployment | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/calendar"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Calendar — Deployment | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/calendar"}]]},"headers":[],"relativePath":"deployment/calendar.md","filePath":"deployment/calendar.md","lastUpdated":1791151472000}'),r={name:"deployment/calendar.md"};function d(l,e,i,c,s,p){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="calendar-—-deployment" tabindex="-1">Calendar — Deployment <a class="header-anchor" href="#calendar-—-deployment" aria-label="Permalink to &quot;Calendar — Deployment&quot;">​</a></h1><h2 id="migrate-only" tabindex="-1">Migrate-only <a class="header-anchor" href="#migrate-only" aria-label="Permalink to &quot;Migrate-only&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span></code></pre></div><p>Creates <code>calendar_events</code>, registers the <code>calendar</code> catalog module (free CRM opt-in), and grants missing default-role permissions (<code>calendar.view|create|update|delete|view_all|manage_integrations</code>).</p><p>Do <strong>not</strong> rely on <code>db:seed</code> in production for catalog/RBAC.</p><h2 id="catalog" tabindex="-1">Catalog <a class="header-anchor" href="#catalog" aria-label="Permalink to &quot;Catalog&quot;">​</a></h2><ul><li><strong>1.1.0</strong> — Task/Lead/Project overlays</li><li><strong>1.2.0</strong> — Meeting invitee list/view ACL (<code>read_only</code> on resource)</li><li><strong>1.3.0</strong> — Manual event shares (<code>calendar_event_shares</code>, viewer/editor)</li><li><strong>1.4.0</strong> — Google/Outlook sync Phase 1 (<code>calendar_provider_connections</code>; <code>external_provider</code>/<code>external_event_id</code> on <code>calendar_events</code>; <code>calendar.manage_integrations</code> permission)</li></ul><p>Bump: migrate-only <code>2026_09_28_000001_bump_calendar_module_version_to_1_3_0</code>, then <code>2026_09_30_150003_bump_calendar_module_version_to_1_4_0</code> (do <strong>not</strong> <code>db:seed</code>).</p><h2 id="environment-calendar-sync-—-1-4-0" tabindex="-1">Environment (Calendar sync — 1.4.0) <a class="header-anchor" href="#environment-calendar-sync-—-1-4-0" aria-label="Permalink to &quot;Environment (Calendar sync — 1.4.0)&quot;">​</a></h2><p>Google/Microsoft OAuth apps are <strong>platform-wide</strong> (unlike Meetings, which is per-workspace). Set in platform <code>.env</code>:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GOOGLE_CALENDAR_CLIENT_ID</code> / <code>GOOGLE_CALENDAR_CLIENT_SECRET</code></td><td>Google Calendar API OAuth app; leave unset to disable Google Connect (SPA shows &quot;not configured&quot;)</td></tr><tr><td><code>MICROSOFT_CALENDAR_CLIENT_ID</code> / <code>MICROSOFT_CALENDAR_CLIENT_SECRET</code> / <code>MICROSOFT_CALENDAR_TENANT</code></td><td>Microsoft Graph OAuth app (<code>MICROSOFT_CALENDAR_TENANT</code> defaults to <code>common</code>); leave unset to disable Outlook Connect</td></tr><tr><td><code>APP_URL</code></td><td>Builds the fixed OAuth callback: <code>/api/oauth/calendar-sync/{provider}/callback</code> (must be HTTPS in production for Google/Microsoft)</td></tr><tr><td><code>FRONTEND_URL</code></td><td>SPA return URL after OAuth (<code>/#/calendar?integrations=…</code>)</td></tr><tr><td><code>CALENDAR_SYNC_PROVIDERS_FAKE</code></td><td>Optional local/CI only; <strong>ignored / forced off in production</strong></td></tr></tbody></table><p>Register the platform callback URL once on each OAuth app (Google Cloud Console / Azure AD app registration) — not per tenant.</p><h2 id="smoke" tabindex="-1">Smoke <a class="header-anchor" href="#smoke" aria-label="Permalink to &quot;Smoke&quot;">​</a></h2><ol><li>Confirm marketplace module <code>calendar</code> exists and is installed on a test workspace.</li><li>Owner: <code>GET /api/tenant/v1/calendar/events</code> → 200.</li><li>Create event → appears on Week (default), Day, Month, and Agenda.</li><li>On Week/Day, drag an event to a new slot → persists after refresh (<code>PUT</code> succeeds; toast “Event rescheduled”).</li><li>Staff without <code>view_all</code> cannot list another user’s <strong>manual</strong> events unless shared.</li><li>Meeting invitee (staff) lists/views the projected meeting event with <code>read_only: true</code>; <code>PUT</code>/<code>cancel</code>/<code>DELETE</code> → 403.</li><li>Share a manual event as viewer → sharee lists with <code>read_only: true</code>; as editor → can mutate.</li><li>Dashboard includes <code>calendar</code> upcoming widget when entitled (invitee/share scope included).</li></ol><p>Go-live: <a href="/deployment/calendar-invitee-acl-1-2-0-production-readiness">Calendar invitee ACL 1.2.0 production readiness</a> · <a href="/deployment/calendar-event-shares-1-3-0-production-readiness">Calendar event shares 1.3.0 production readiness</a> · <a href="/deployment/calendar-google-outlook-sync-1-4-0-production-readiness">Calendar Google/Outlook sync 1.4.0 production readiness</a>.</p><h3 id="smoke-calendar-sync-—-1-4-0" tabindex="-1">Smoke (Calendar sync — 1.4.0) <a class="header-anchor" href="#smoke-calendar-sync-—-1-4-0" aria-label="Permalink to &quot;Smoke (Calendar sync — 1.4.0)&quot;">​</a></h3><ol start="9"><li>Admin with <code>calendar.manage_integrations</code>: Calendar → <strong>Sync</strong> lists Google + Microsoft; Connect disabled when platform OAuth env is unset.</li><li>After Connect (staging OAuth app): create manual event → appears in provider calendar; update/cancel in EloSync propagates (async — confirm Horizon <strong><code>calendar-sync</code></strong> worker).</li><li>Organizer disconnects provider → new manual events no longer push (existing provider copies remain).</li></ol><h2 id="rollback-note" tabindex="-1">Rollback note <a class="header-anchor" href="#rollback-note" aria-label="Permalink to &quot;Rollback note&quot;">​</a></h2><p>Catalog/permission data migrations are intentionally irreversible; use a forward migration to retire the module if required. Roll the <strong>1.4.0</strong> bump <code>down</code> → <strong>1.3.0</strong> → <strong>1.2.0</strong> only with matching code rollback.</p>',19)])])}const g=o(r,[["render",d]]);export{m as __pageData,g as default};
